<?php

namespace App\Models;

use App\Models\Concerns\BelongsToSchool;
use Illuminate\Database\Eloquent\Model;
use Illuminate\Database\Eloquent\Relations\BelongsTo;
use Illuminate\Database\Eloquent\Relations\HasMany;

/**
 * Generated by ResultPublisher from GradeCalculator; never edited by hand.
 */
class ExamResult extends Model
{
    use BelongsToSchool;

    protected $fillable = [
        'exam_id', 'enrollment_id', 'total_marks', 'gpa', 'gpa_without_optional', 'letter', 'fail_count',
        'merit_position_section', 'merit_position_class',
    ];

    protected function casts(): array
    {
        return [
            'total_marks' => 'decimal:2',
            'gpa' => 'decimal:2',
            'gpa_without_optional' => 'decimal:2',
            'fail_count' => 'integer',
            'merit_position_section' => 'integer',
            'merit_position_class' => 'integer',
            'sms_sent_at' => 'immutable_datetime',
        ];
    }

    /**
     * @return BelongsTo<Exam, $this>
     */
    public function exam(): BelongsTo
    {
        return $this->belongsTo(Exam::class);
    }

    /**
     * @return BelongsTo<Enrollment, $this>
     */
    public function enrollment(): BelongsTo
    {
        return $this->belongsTo(Enrollment::class);
    }

    /**
     * @return HasMany<SubjectResult, $this>
     */
    public function subjectResults(): HasMany
    {
        return $this->hasMany(SubjectResult::class);
    }
}
